/* cppi::0b20a539382e32195a577df2d556c500b60c145ea90204e95962c8b994a15fd2 */
select business_date as date_, security_id, 'EUGBR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-17' and business_date <= date '2025-06-17' and weight_ndo>0 and id_cppib_index = 'EUGBR_GR_USD_0_0' and security_id is not null

/* cppi::f76e26a1716c74bbcf4e2717e78a9ac283be871aadfad5f278de020ec30245b4 */
